let tæller = 1;

function getRandomItem(arr) {
  const randomIndex = Math.floor(Math.random() * arr.length);
  return arr[randomIndex];
}

function startNytSpil() {
  currentCity = getRandomItem(byer)
  console.log(currentCity.byNavn)
  rigtigtSvar.textContent = "";
  forkertSvar.textContent = "";
  tæller = 1;
}

nytSpil.addEventListener("click", () => {
  startNytSpil()
  fåEtHint()
});

function fåEtHint() {
  randomHint = getRandomItem(currentCity.hints);
  hintText.textContent = "Dit hint er: " + randomHint;
  console.log("Dine hints som bliver talt: " + tæller)
  antalAfGæt.textContent = "Du har brugt " + tæller++ + " hint(s)"
}

hintKnap.addEventListener("click", () => {
  fåEtHint()
});


sendSvar.addEventListener("click", () => {
  if (currentCity.byNavn.toLowerCase().trim() === skrivefelt.value.toLowerCase().trim()) {
    rigtigtSvar.textContent = "Tilykke du har gættet det rigtigt! Tryk på start nyt spil igen.";
    forkertSvar.textContent = "";
    skrivefelt.value = ""
  } else {
    forkertSvar.textContent = "Forkert";
    skrivefelt.value = ""
  }
});

givOp.addEventListener("click", () => {
  alert("Det rigtige svar var " + currentCity.byNavn);
  skrivefelt.value = ""
  startNytSpil()
  fåEtHint()
})

